struct Writer {FILE* f;explicit Writer(const std::string& p):f(std::fopen(p.c_str(),"wx")){if(!f)throw std::runtime_error("exclusive gain-frame wire");}void word(u64 x){u8 b[8];store_be32(b,u32(x>>32));store_be32(b+4,u32(x));if(std::fwrite(b,1,8,f)!=8)throw std::runtime_error("gain-frame word");}void close(){if(std::fclose(f))throw std::runtime_error("gain-frame close");}};
